const addCount = (moduleId, importName) => {
  const symbol = importName === "*" ? "" : " - " + chalk.magenta(importName);
  const key = path.relative(process.cwd(), moduleId) + symbol;
  if (counts[key] == null) {
    counts[key] = 1;
  } else {
    counts[key] += 1;
  }
};
